 if(packed.uncompressed_bytes>33554432||packed.compressed_bytes>16777216||packed.data.length>22369624)throw new Error('Snapshot exceeds fixed presentation allocation limits.');
 const bytes=Uint8Array.from(atob(packed.data),c=>c.charCodeAt(0));
 if(bytes.byteLength!==packed.compressed_bytes)throw new Error('Snapshot compressed length mismatch.');
 const reader=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip')).getReader();
 const chunks=[];let total=0;
 try{while(true){const {done,value}=await reader.read();if(done)break;total+=value.byteLength;if(total>packed.uncompressed_bytes)throw new Error('Snapshot decoded length exceeds its declared size.');chunks.push(value);}}
 catch(error){try{await reader.cancel();}catch{}throw error;}
 finally{reader.releaseLock();}
 if(total!==packed.uncompressed_bytes)throw new Error('Snapshot decoded length mismatch.');
 const raw=new Uint8Array(total);let offset=0;for(const chunk of chunks){raw.set(chunk,offset);offset+=chunk.byteLength;}chunks.length=0;
 const actual=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',raw)),value=>value.toString(16).padStart(2,'0')).join('');
