 if(!decoded||typeof decoded!=='object'||Array.isArray(decoded)||!decoded.records||!['architecture','revision','run','result','note'].every(kind=>Array.isArray(decoded.records[kind])))throw new Error('Decoded snapshot has no supported canonical record collections.');
